// Common flags (requires sys/stat.h for mode)
const int flags = O_RDWR | O_CREAT | O_EXCL;
const mode_t mode = 0600;

// 1. Obtain directory file descriptor
int dirfd = open("/var/log/", O_RDONLY | O_DIRECTORY);

// 2. Open file relative to dirfd (Safe path resolution)
// Attempts to open /var/log/audit/log.1
int log_fd = openat(dirfd, "audit/log.1", flags, mode);

// 3. Using AT_FDCWD (Equivalent to standard open())
// Opens /etc/hosts relative to current working directory
int host_fd = openat(AT_FDCWD, "/etc/hosts", O_RDONLY);

// 4. Cleanup
close(dirfd);
close(log_fd);
close(host_fd);
